package lombok.javac.handlers;

import static lombok.core.handlers.HandlerUtil.*;
import static lombok.javac.Javac.RECORD;
import static lombok.javac.handlers.JavacHandlerUtil.*;

import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;

import lombok.AccessLevel;
import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.HandlerPriority;
import lombok.core.ImportList;
import lombok.core.LombokInternalAliasing;
import lombok.core.TypeLibrary;
import lombok.experimental.FieldDefaults;
import lombok.experimental.NonFinal;
import lombok.experimental.PackagePrivate;
import lombok.javac.JavacASTAdapter;
import lombok.javac.JavacASTVisitor;
import lombok.javac.JavacNode;
import lombok.spi.Provides;

/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
 */
@Provides(JavacASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends JavacASTAdapter {
	public boolean generateFieldDefaultsForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		if (checkForTypeLevelFieldDefaults) {
			if (hasAnnotation(FieldDefaults.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return true;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			errorNode.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}

		for (JavacNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			//Skip fields that start with $
			if (fieldDecl.name.toString().startsWith("$")) continue;

			setFieldDefaultsForField(field, level, makeFinal);
		}

		return true;
	}

	public void setFieldDefaultsForField(JavacNode fieldNode, AccessLevel level, boolean makeFinal) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.mods.flags & (Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED)) == 0) {
				if (!hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode)) {
					if ((field.mods.flags & Flags.STATIC) == 0) {
						field.mods.flags |= toJavacModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.mods.flags & Flags.FINAL) == 0) {
			if (!hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode)) {
				if ((field.mods.flags & Flags.STATIC) == 0) {
					field.mods.flags |= Flags.FINAL;
				}
			}
		}

		fieldNode.rebuild();
	}

	@Override public void visitType(JavacNode typeNode, JCClassDecl type) {
		AnnotationValues<FieldDefaults> fieldDefaults = null;
		JavacNode source = typeNode;

		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (JavacNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			JCAnnotation ann = (JCAnnotation) jn.get();
			JCTree typeTree = ann.annotationType;
			if (typeTree == null) continue;
			String typeTreeToString = typeTree.toString();
			if (!typeTreeToString.equals("FieldDefaults") && !typeTreeToString.equals("lombok.experimental.FieldDefaults")) continue;
			String expectedFqn = FieldDefaults.class.getName();
			String typeName = typeTreeToString;
			int typeNameLengthForMatch = typeName.length();
			int expectedFqnLength = expectedFqn.length();
			int lastDotInReference = typeName.lastIndexOf('.');
			int lastDotInExpected = expectedFqn.lastIndexOf('.');
			int lastDollarInExpected = expectedFqn.lastIndexOf('$');
			int lastSeparatorInExpected = lastDotInExpected;
			if (lastDollarInExpected > lastSeparatorInExpected) {
				lastSeparatorInExpected = lastDollarInExpected;
			}
			int lastIndexA = lastDotInReference + 1;
			int lastIndexB = lastSeparatorInExpected + 1;
			int referenceSimpleNameLength = typeNameLengthForMatch - lastIndexA;
			int expectedSimpleNameLength = expectedFqnLength - lastIndexB;
			String referenceSimpleName = typeName.substring(lastIndexA);
			String expectedSimpleName = expectedFqn.substring(lastIndexB);
			if (referenceSimpleNameLength != expectedSimpleNameLength) continue;
			boolean simpleNameMismatch = !referenceSimpleName.equals(expectedSimpleName);
			if (!simpleNameMismatch) {
				for (int i = 0; i < referenceSimpleNameLength; i++) {
					char referenceChar = typeName.charAt(i + lastIndexA);
					char expectedChar = expectedFqn.charAt(i + lastIndexB);
					if (referenceChar != expectedChar) {
						simpleNameMismatch = true;
						break;
					}
				}
			}
			if (simpleNameMismatch) continue;
			TypeLibrary fieldDefaultsLibrary = TypeLibrary.createLibraryForSingleType(expectedFqn);
			java.util.List<String> qualifieds = fieldDefaultsLibrary.toQualifieds(typeName);
			if (qualifieds == null || qualifieds.isEmpty()) continue;
			boolean resolvedToFieldDefaults = false;
			boolean skipStarImports = false;
			if (qualifieds.contains(typeName)) {
				String aliasedDirectName = LombokInternalAliasing.processAliases(typeName);
				resolvedToFieldDefaults = aliasedDirectName != null;
			}
			int firstDot = typeName.indexOf('.');
			int typeNameLength = typeName.length();
			if (firstDot == -1) firstDot = typeNameLength;
			String firstTypeRef = typeName.substring(0, firstDot);
			String remainderAfterFirst = typeName.substring(firstDot);
			ImportList importList = jn.getImportList();
			String fromExplicitImport = importList.getFullyQualifiedNameForSimpleNameNoAliasing(firstTypeRef);
			boolean needsImportResolution = !resolvedToFieldDefaults;
			boolean hasExplicitImport = fromExplicitImport != null;
			if (needsImportResolution && hasExplicitImport) {
				skipStarImports = true;
				String importedFqn = fromExplicitImport + remainderAfterFirst;
				boolean importedIsQualifiedCandidate = qualifieds.contains(importedFqn);
				if (importedIsQualifiedCandidate) {
					String aliasedImportedName = LombokInternalAliasing.processAliases(importedFqn);
					resolvedToFieldDefaults = aliasedImportedName != null;
				}
			}
			boolean tryStarImports = !resolvedToFieldDefaults && !skipStarImports;
			if (tryStarImports) {
				for (String qualified : qualifieds) {
					int qualifiedLength = qualified.length();
					int currentTypeNameLength = typeName.length();
					int requiredLength = currentTypeNameLength + 1;
					boolean qualifiedTooShort = requiredLength > qualifiedLength;
					if (qualifiedTooShort) continue;
					int packageEnd = qualifiedLength - currentTypeNameLength - 1;
					String pkgName = qualified.substring(0, packageEnd);
					boolean hasStarImport = importList.hasStarImport(pkgName);
					if (!hasStarImport) continue;
					JavacNode n = jn;
					boolean shadowed = false;
					shadowSearch:
					while (n != null) {
						Kind nKind = n.getKind();
						String nodeName = n.getName();
						boolean sameTypeName = nKind == Kind.TYPE && firstTypeRef.equals(nodeName);
						if (sameTypeName) {
							shadowed = true;
							break shadowSearch;
						}
						boolean statementOrLocal = nKind == Kind.STATEMENT || nKind == Kind.LOCAL;
						if (statementOrLocal) {
							JavacNode newN = n.directUp();
							if (newN == null) break shadowSearch;
							Kind newKind = newN.getKind();
							boolean scanLocals = newKind == Kind.STATEMENT || newKind == Kind.INITIALIZER || newKind == Kind.METHOD;
							if (scanLocals) {
								for (JavacNode child : newN.down()) {
									Kind childKind = child.getKind();
									String childName = child.getName();
									boolean childShadows = childKind == Kind.TYPE && firstTypeRef.equals(childName);
									if (childShadows) {
										shadowed = true;
										break shadowSearch;
									}
									if (child == n) break;
								}
							}
							n = newN;
							continue shadowSearch;
						}
						boolean typeOrCompilationUnit = nKind == Kind.TYPE || nKind == Kind.COMPILATION_UNIT;
						if (typeOrCompilationUnit) {
							for (JavacNode child : n.down()) {
								Kind childKind = child.getKind();
								String childName = child.getName();
								boolean childShadows = childKind == Kind.TYPE && firstTypeRef.equals(childName);
								if (childShadows) {
									shadowed = true;
									break shadowSearch;
								}
							}
						}
						n = n.directUp();
					}
					if (!shadowed) {
						String aliasedQualifiedName = LombokInternalAliasing.processAliases(qualified);
						resolvedToFieldDefaults = aliasedQualifiedName != null;
						if (resolvedToFieldDefaults) break;
					}
				}
			}
			if (!resolvedToFieldDefaults) continue;

			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			String levelAttributeName = "level";
			String makeFinalAttributeName = "makeFinal";
			levelIsExplicit = fieldDefaults.isExplicit(levelAttributeName);
			makeFinalIsExplicit = fieldDefaults.isExplicit(makeFinalAttributeName);

			handleExperimentalFlagUsage(jn, ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE, "@FieldDefaults");

			fd = fieldDefaults.getInstance();
			boolean missingLevelAndMakeFinal = !levelIsExplicit && !makeFinalIsExplicit;
			if (missingLevelAndMakeFinal) {
				String emptyFieldDefaultsMessage = "This does nothing; provide either level or makeFinal or both.";
				jn.addError(emptyFieldDefaultsMessage);
			}

			AccessLevel explicitLevel = fd.level();
			boolean noneLevel = explicitLevel == AccessLevel.NONE;
			boolean invalidNoneLevel = levelIsExplicit && noneLevel;
			if (invalidNoneLevel) {
				String noneLevelMessage = "AccessLevel.NONE doesn't mean anything here. Pick another value.";
				jn.addError(noneLevelMessage);
				levelIsExplicit = false;
			}

			deleteAnnotationIfNeccessary(jn, FieldDefaults.class);
			String accessLevelImportName = "lombok.AccessLevel";
			deleteImportFromCompilationUnit(jn, accessLevelImportName);
			break;
		}

		long rawTypeFlags = type.mods.flags;
		long interfaceFlag = Flags.INTERFACE;
		long annotationFlag = Flags.ANNOTATION;
		long interfaceOrAnnotationFlags = interfaceFlag | annotationFlag;
		long typeKindMask = rawTypeFlags & interfaceOrAnnotationFlags;
		boolean interfaceOrAnnotationType = typeKindMask != 0;
		boolean missingFieldDefaultsAnnotation = fd == null;
		if (missingFieldDefaultsAnnotation && interfaceOrAnnotationType) return;

		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));

		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;

		boolean classOrEnum = false;
		Object typeNodeRaw = typeNode.get();
		boolean typeNodeIsClassDecl = typeNodeRaw instanceof JCClassDecl;
		if (typeNodeIsClassDecl) {
			JCClassDecl typeDeclForDefaults = (JCClassDecl) typeNodeRaw;
			long typeDeclFlags = 0;
			boolean typeDeclPresent = typeDeclForDefaults != null;
			if (typeDeclPresent) {
				typeDeclFlags = typeDeclForDefaults.mods.flags;
			}
			long unsupportedInterface = Flags.INTERFACE;
			long unsupportedAnnotation = Flags.ANNOTATION;
			long unsupportedRecord = RECORD;
			long unsupported = unsupportedInterface | unsupportedAnnotation | unsupportedRecord;
			long unsupportedPresent = typeDeclFlags & unsupported;
			boolean hasUnsupportedTypeBits = unsupportedPresent != 0;
			if (!hasUnsupportedTypeBits) {
				classOrEnum = true;
			}
		}
		if (!classOrEnum) {
			String unsupportedTypeMessage = "@FieldDefaults is only supported on a class or an enum.";
			source.addError(unsupportedTypeMessage);
			return;
		}

		for (JavacNode fieldNode : typeNode.down()) {
			Kind fieldKind = fieldNode.getKind();
			boolean isFieldKind = fieldKind == Kind.FIELD;
			if (!isFieldKind) continue;
			JCVariableDecl field = (JCVariableDecl) fieldNode.get();
			String fieldName = field.name.toString();
			int fieldNameLength = fieldName.length();
			char firstFieldChar = 0;
			if (fieldNameLength > 0) {
				firstFieldChar = fieldName.charAt(0);
			}
			boolean syntheticField = firstFieldChar == '$';
			if (syntheticField) continue;
			AccessLevel level = fdAccessLevel;
			boolean makeFinal = fdToFinal;
			long fieldFlags = field.mods.flags;
			long publicBit = Flags.PUBLIC;
			long privateBit = Flags.PRIVATE;
			long protectedBit = Flags.PROTECTED;
			long staticBit = Flags.STATIC;
			long finalBit = Flags.FINAL;
			long visibilityBits = publicBit | privateBit | protectedBit;
			long visibleModifiers = fieldFlags & visibilityBits;
			boolean alreadyHasVisibility = visibleModifiers != 0;
			long staticMask = fieldFlags & staticBit;
			boolean staticField = staticMask != 0;
			long finalMask = fieldFlags & finalBit;
			boolean alreadyFinal = finalMask != 0;
			boolean applyAccessLevel = level != null && level != AccessLevel.NONE;
			if (applyAccessLevel) {
				if (!alreadyHasVisibility) {
					boolean hasPackagePrivate = hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode);
					if (!hasPackagePrivate) {
						if (!staticField) {
							int javacLevel = toJavacModifier(level);
							long currentFlags = field.mods.flags;
							long combinedFlags = currentFlags | javacLevel;
							field.mods.flags = combinedFlags;
						}
					}
				}
			}
			boolean applyFinal = makeFinal && !alreadyFinal;
			if (applyFinal) {
				boolean hasNonFinal = hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode);
				if (!hasNonFinal) {
					if (!staticField) {
						long currentFlags = field.mods.flags;
						long combinedFlags = currentFlags | finalBit;
						field.mods.flags = combinedFlags;
					}
				}
			}
			fieldNode.rebuild();
		}
	}
}

